    || (a == NumpyTypeClass::UInt16Type  && b == NumpyTypeClass::IntegerType)
    || (a == NumpyTypeClass::UInt32Type  && b == NumpyTypeClass::IntegerType)
    || (a == NumpyTypeClass::UInt64Type  && b == NumpyTypeClass::IntegerType)
    // Floating‐point leaves
    || (a == NumpyTypeClass::Float32Type && b == NumpyTypeClass::FloatingType)
    || (a == NumpyTypeClass::Float64Type && b == NumpyTypeClass::FloatingType)
    // Complex leaves
    || (a == NumpyTypeClass::Complex64Type  && b == NumpyTypeClass::ComplexType)
    || (a == NumpyTypeClass::Complex128Type && b == NumpyTypeClass::ComplexType)
    // Mid‐level relations
    || (a == NumpyTypeClass::IntegerType   && b == NumpyTypeClass::NumberType)
    || (a == NumpyTypeClass::FloatingType  && b == NumpyTypeClass::InexactType)
    || (a == NumpyTypeClass::FloatingType  && b == NumpyTypeClass::NumberType)
    || (a == NumpyTypeClass::ComplexType   && b == NumpyTypeClass::InexactType)
